    {detail==='contracts'&&table('contracts',currentContracts,true)}
    {detail==='events'&&<CustomerConsultations initialRows={5} matchPanelHeight key={customer?.id||'empty'} customer={details.customer} onSave={status?.ready?(record,value)=>saveDetail(record,'consultations',value):undefined}/>}
    {detail==='disclosure'&&<CustomerDisclosure key={customer?.id||'empty'} customer={details.customer} onSave={status?.ready?(record,value)=>saveDetail(record,'disclosure',value):undefined}/>}

